#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""Process an HWPX template with JSON-driven placeholder replacement.

Task requirements implemented:
- Exploratory pass FIRST: ZIP listing + raw XML dump of section file(s)
- Parse XML structurally (no raw XML string replacement)
- Replace all {{...}} placeholders using keys from project_proposal.json
- Normalize budget: remove commas, keep currency symbol (e.g. ₩450,000,000 -> ₩450000000)
- Append computed month spans to 단계1/2/3 schedule lines based on date ranges already present
- Keep Korean labels/static lines unchanged except where placeholders are
- Remove layout-cache elements named linesegarray from every paragraph whose text was modified
- Rebuild output HWPX, preserving all other ZIP entries exactly
- Validate output for placeholders, month spans, budget commas, and linesegarray removal

Output: /root/project_proposal_ready.hwpx

Notes:
- Uses xml.etree.ElementTree (stdlib). lxml is preferred in general, but isn't
  available in this runtime.
"""

from __future__ import annotations

import json
import os
import re
import sys
import zipfile
import xml.etree.ElementTree as ET
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple


DATE_YM_RE = re.compile(r"(\d{4})[.\-/](\d{1,2})(?:[.\-/](\d{1,2}))?")
MONTH_SPAN_RE = re.compile(r"\(\s*(\d+)\s*개월\s*\)")

# Stage markers may appear as "1단계" or "단계1" depending on author.
STAGE_PATTERNS = [
    re.compile(r"\b([1-3])\s*단계\b"),
    re.compile(r"단계\s*([1-3])\b"),
]

# Currency normalization: keep the leading symbol, strip commas from digits.
CURRENCY_RE = re.compile(r"([₩$€¥])\s*([0-9][0-9,]*)")

# Placeholders: allow Korean and other characters; stop at braces.
PLACEHOLDER_RE = re.compile(r"\{\{\s*([^{}]+?)\s*\}\}")


def eprint(*args, **kwargs):
    print(*args, file=sys.stderr, **kwargs)


@dataclass
class ReplacementSummary:
    placeholders_replaced: Dict[str, int] = field(default_factory=dict)
    placeholders_missing_keys: Dict[str, int] = field(default_factory=dict)
    budget_normalizations: int = 0
    stage_month_appends: Dict[str, int] = field(default_factory=dict)  # stage -> count
    linesegarray_removed: int = 0
    modified_paragraph_ids: List[str] = field(default_factory=list)


def find_input_paths() -> Tuple[str, str, str]:
    candidates_hwpx = [
        "/root/project_proposal_template.hwpx",
        os.path.join(os.getcwd(), "project_proposal_template.hwpx"),
    ]
    candidates_json = [
        "/root/project_proposal.json",
        os.path.join(os.getcwd(), "project_proposal.json"),
    ]

    hwpx_path = next((p for p in candidates_hwpx if os.path.exists(p)), None)
    json_path = next((p for p in candidates_json if os.path.exists(p)), None)
    out_path = "/root/project_proposal_ready.hwpx"

    if not hwpx_path:
        raise FileNotFoundError("Template HWPX not found in /root or current directory")
    if not json_path:
        raise FileNotFoundError("JSON data file not found in /root or current directory")

    return hwpx_path, json_path, out_path


def load_json(json_path: str) -> Dict[str, str]:
    with open(json_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    out: Dict[str, str] = {}
    for k, v in data.items():
        if v is None:
            out[k] = ""
        elif isinstance(v, (dict, list)):
            out[k] = json.dumps(v, ensure_ascii=False)
        else:
            out[k] = str(v)
    return out


def list_zip(zip_path: str) -> List[str]:
    with zipfile.ZipFile(zip_path, "r") as zf:
        return zf.namelist()


def choose_content_xmls(zip_names: List[str]) -> List[str]:
    xmls = [n for n in zip_names if n.lower().endswith(".xml")]

    section_like = [
        n
        for n in xmls
        if re.search(r"(^|/)Contents/section\d+\.xml$", n)
        or re.search(r"(^|/)Contents/Section\d+\.xml$", n)
    ]

    if not section_like:
        section_like = [n for n in xmls if "Contents/" in n]

    if not section_like:
        section_like = xmls

    seen = set()
    out = []
    for n in section_like:
        if n not in seen:
            out.append(n)
            seen.add(n)
    return out


def dump_raw_xml(zip_path: str, xml_paths: List[str]) -> Dict[str, bytes]:
    raw: Dict[str, bytes] = {}
    with zipfile.ZipFile(zip_path, "r") as zf:
        for xp in xml_paths:
            try:
                data = zf.read(xp)
            except KeyError:
                continue
            raw[xp] = data

            print("\n" + "=" * 80)
            print(f"[RAW XML DUMP] {xp} ({len(data)} bytes)")
            print("=" * 80)
            print(data.decode("utf-8", errors="replace"))
    return raw


def localname(tag: str) -> str:
    # ElementTree uses {uri}local
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def element_namespace_uri(tag: str) -> Optional[str]:
    if tag.startswith("{"):
        return tag[1:].split("}", 1)[0]
    return None


def build_parent_map(root: ET.Element) -> Dict[ET.Element, ET.Element]:
    parent: Dict[ET.Element, ET.Element] = {}
    for p in root.iter():
        for c in list(p):
            parent[c] = p
    return parent


def iter_text_elements(root: ET.Element):
    for el in root.iter():
        if localname(el.tag) == "t":
            yield el


def iter_paragraph_elements(root: ET.Element):
    for el in root.iter():
        if localname(el.tag) == "p":
            yield el


def paragraph_text(par: ET.Element) -> str:
    parts: List[str] = []
    for t in par.iter():
        if localname(t.tag) == "t" and t.text is not None:
            parts.append(t.text)
    return "".join(parts)


def find_stage_number(text: str) -> Optional[str]:
    for pat in STAGE_PATTERNS:
        m = pat.search(text)
        if m:
            return m.group(1)
    return None


def extract_year_months(text: str) -> List[Tuple[int, int]]:
    out: List[Tuple[int, int]] = []
    for y, m, _d in DATE_YM_RE.findall(text):
        try:
            yy = int(y)
            mm = int(m)
        except ValueError:
            continue
        if 1 <= mm <= 12:
            out.append((yy, mm))
    return out


def compute_month_span_inclusive(start_ym: Tuple[int, int], end_ym: Tuple[int, int]) -> int:
    sy, sm = start_ym
    ey, em = end_ym
    months = (ey - sy) * 12 + (em - sm) + 1
    if months < 1:
        return 1
    return months


def append_stage_month_span(text: str) -> Tuple[str, Optional[int], Optional[str]]:
    stage = find_stage_number(text)
    if stage is None:
        return text, None, None

    if MONTH_SPAN_RE.search(text):
        return text, None, stage

    yms = extract_year_months(text)
    if not yms:
        return text, None, stage

    if len(yms) >= 2:
        start_ym, end_ym = yms[0], yms[1]
    else:
        start_ym = end_ym = yms[0]

    months = compute_month_span_inclusive(start_ym, end_ym)

    spacer = "" if text.endswith(" ") else " "
    return text + f"{spacer}({months}개월)", months, stage


def normalize_budget_in_text(text: str) -> Tuple[str, int]:
    count = 0

    def repl(m: re.Match) -> str:
        nonlocal count
        sym = m.group(1)
        digits = m.group(2)
        if "," in digits:
            count += 1
            digits = digits.replace(",", "")
        return f"{sym}{digits}"

    return CURRENCY_RE.sub(repl, text), count


def replace_placeholders_in_text(text: str, values: Dict[str, str], summary: ReplacementSummary) -> str:
    def repl(m: re.Match) -> str:
        key = m.group(1).strip()
        if key in values:
            summary.placeholders_replaced[key] = summary.placeholders_replaced.get(key, 0) + 1
            return values[key]
        summary.placeholders_missing_keys[key] = summary.placeholders_missing_keys.get(key, 0) + 1
        return m.group(0)

    return PLACEHOLDER_RE.sub(repl, text)


def find_ancestor_paragraph(node: ET.Element, parent_map: Dict[ET.Element, ET.Element]) -> Optional[ET.Element]:
    cur = node
    while cur in parent_map:
        cur = parent_map[cur]
        if localname(cur.tag) == "p":
            return cur
    return None


def remove_linesegarray_from_paragraph(par: ET.Element, parent_map: Dict[ET.Element, ET.Element], summary: ReplacementSummary):
    # Find all descendant linesegarray elements and remove from their immediate parent.
    to_remove: List[ET.Element] = []
    for el in par.iter():
        if localname(el.tag) == "linesegarray":
            to_remove.append(el)

    for el in to_remove:
        parent = parent_map.get(el)
        if parent is None:
            continue
        parent.remove(el)
        summary.linesegarray_removed += 1


def transform_section_xml(xml_bytes: bytes, values: Dict[str, str], label: str) -> Tuple[bytes, ReplacementSummary]:
    root = ET.fromstring(xml_bytes)

    print("\n" + "-" * 80)
    print(f"[INSPECT] {label}")
    print(f"Root tag: {root.tag}")
    ns_uri = element_namespace_uri(root.tag)
    if ns_uri:
        print(f"Root namespace URI: {ns_uri}")
    else:
        print("Root namespace URI: (none)")

    parent_map = build_parent_map(root)
    summary = ReplacementSummary()

    modified_paragraphs: List[ET.Element] = []
    modified_set = set()

    # Pass 1: per-<t> edits (preserve runs)
    for t in iter_text_elements(root):
        if t.text is None:
            continue

        original = t.text
        new = original

        if "{{" in new and "}}" in new:
            new = replace_placeholders_in_text(new, values, summary)

        new, bcount = normalize_budget_in_text(new)
        summary.budget_normalizations += bcount

        appended, _months, stage = append_stage_month_span(new)
        if appended != new:
            new = appended
            if stage is not None:
                summary.stage_month_appends[stage] = summary.stage_month_appends.get(stage, 0) + 1

        if new != original:
            t.text = new
            par = find_ancestor_paragraph(t, parent_map)
            if par is not None and id(par) not in modified_set:
                modified_set.add(id(par))
                modified_paragraphs.append(par)

    # Pass 2: paragraph-level fix-up (handles placeholders split across multiple <t> nodes)
    for par in iter_paragraph_elements(root):
        combined = paragraph_text(par)
        if "{{" not in combined and "단계" not in combined and not CURRENCY_RE.search(combined):
            continue

        new_combined = combined

        if "{{" in new_combined and "}}" in new_combined:
            new_combined = replace_placeholders_in_text(new_combined, values, summary)

        new_combined, bcount = normalize_budget_in_text(new_combined)
        summary.budget_normalizations += bcount

        appended, _months, stage = append_stage_month_span(new_combined)
        if appended != new_combined:
            new_combined = appended
            if stage is not None:
                summary.stage_month_appends[stage] = summary.stage_month_appends.get(stage, 0) + 1

        if new_combined == combined:
            continue

        t_nodes = [n for n in par.iter() if localname(n.tag) == "t"]
        if not t_nodes:
            continue

        old_lens = [len(n.text or "") for n in t_nodes]
        remaining = new_combined
        for i, node in enumerate(t_nodes):
            if i == len(t_nodes) - 1:
                chunk = remaining
            else:
                take = old_lens[i]
                chunk = remaining[:take]
            node.text = chunk
            remaining = remaining[len(chunk):]

        if id(par) not in modified_set:
            modified_set.add(id(par))
            modified_paragraphs.append(par)

    # Remove layout-cache elements for any paragraph we modified
    for par in modified_paragraphs:
        remove_linesegarray_from_paragraph(par, parent_map, summary)
        pid = par.get("id")
        if pid is None:
            # fallback identifier
            pid = f"(no-id)@{label}#{len(summary.modified_paragraph_ids)}"
        summary.modified_paragraph_ids.append(pid)

    out_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    return out_bytes, summary


def clone_zipinfo(info: zipfile.ZipInfo) -> zipfile.ZipInfo:
    zi = zipfile.ZipInfo(filename=info.filename, date_time=info.date_time)
    zi.compress_type = info.compress_type
    zi.comment = info.comment
    zi.extra = info.extra
    zi.create_system = info.create_system
    zi.create_version = info.create_version
    zi.extract_version = info.extract_version
    zi.flag_bits = info.flag_bits
    zi.internal_attr = info.internal_attr
    zi.external_attr = info.external_attr
    return zi


def build_output_zip(template_path: str, out_path: str, modified_xml: Dict[str, bytes]):
    with zipfile.ZipFile(template_path, "r") as zin:
        with zipfile.ZipFile(out_path, "w") as zout:
            for info in zin.infolist():
                data = zin.read(info.filename)
                if info.filename in modified_xml:
                    data = modified_xml[info.filename]
                zout.writestr(clone_zipinfo(info), data)


def validate_output(out_path: str, modified_xml_paths: List[str], expected_stage_months: Dict[str, Optional[int]]):
    results = {
        "zip_valid": False,
        "no_placeholders": True,
        "stage_month_spans_ok": True,
        "budget_commas_removed": True,
        "korean_stage_labels_present": True,
        "linesegarray_absent_in_modified_paragraphs": True,
        "details": [],
    }

    with zipfile.ZipFile(out_path, "r") as zf:
        bad = zf.testzip()
        results["zip_valid"] = (bad is None)
        if bad is not None:
            results["details"].append(f"Zip testzip failed at: {bad}")

        for xp in modified_xml_paths:
            xml_bytes = zf.read(xp)
            xml_text = xml_bytes.decode("utf-8", errors="replace")

            if "{{" in xml_text or "}}" in xml_text:
                results["no_placeholders"] = False
                results["details"].append(f"Placeholders still present in {xp}")

            if re.search(r"[₩$€¥]\s*\d{1,3}(,\d{3})+", xml_text):
                results["budget_commas_removed"] = False
                results["details"].append(f"Found currency amount with commas in {xp}")

            root = ET.fromstring(xml_bytes)

            stage_found = {"1": False, "2": False, "3": False}
            stage_ok = {"1": True, "2": True, "3": True}

            for par in iter_paragraph_elements(root):
                txt = paragraph_text(par)
                stage = find_stage_number(txt)
                if stage is None or stage not in stage_found:
                    continue

                stage_found[stage] = True

                mm = MONTH_SPAN_RE.search(txt)
                if not mm:
                    stage_ok[stage] = False
                    results["details"].append(f"Missing month span on stage{stage} line in {xp}: {txt}")
                    continue

                actual = int(mm.group(1))
                yms = extract_year_months(txt)
                if yms:
                    if len(yms) >= 2:
                        computed = compute_month_span_inclusive(yms[0], yms[1])
                    else:
                        computed = 1
                    if computed != actual:
                        stage_ok[stage] = False
                        results["details"].append(
                            f"Stage{stage} month span mismatch in {xp}: computed {computed}, found {actual}"
                        )

                exp = expected_stage_months.get(stage)
                if exp is not None and exp != actual:
                    # Not fatal by itself (task requires compute-from-dates), but record.
                    results["details"].append(
                        f"Stage{stage} months differ from expected ({exp}) in {xp}: found {actual}"
                    )

            if not all(stage_found.values()):
                results["korean_stage_labels_present"] = False
                results["details"].append(f"Not all stage lines found in {xp}: {stage_found}")

            if not all(stage_ok.values()):
                results["stage_month_spans_ok"] = False

            # Ensure no linesegarray exists inside paragraphs that look modified.
            for par in iter_paragraph_elements(root):
                txt = paragraph_text(par)
                if not txt:
                    continue
                modified_like = (
                    bool(PLACEHOLDER_RE.search(txt))
                    or ("개월" in txt and find_stage_number(txt) is not None)
                    or bool(CURRENCY_RE.search(txt))
                )
                if not modified_like:
                    continue

                has_linesegarray = any(localname(el.tag) == "linesegarray" for el in par.iter())
                if has_linesegarray:
                    results["linesegarray_absent_in_modified_paragraphs"] = False
                    results["details"].append(f"Found linesegarray inside modified-like paragraph in {xp}: {txt}")
                    break

    return results


def main():
    hwpx_path, json_path, out_path = find_input_paths()

    print(f"Template HWPX: {hwpx_path}")
    print(f"JSON data:     {json_path}")
    print(f"Output HWPX:   {out_path}")

    values = load_json(json_path)

    print("\n" + "=" * 80)
    print("[EXPLORATION] ZIP listing")
    print("=" * 80)
    zip_names = list_zip(hwpx_path)
    for n in zip_names:
        print(n)

    xml_paths = [n for n in zip_names if n.lower().endswith(".xml")]
    print("\nXML files found:")
    for n in xml_paths:
        print(f"  - {n}")

    content_xmls = choose_content_xmls(zip_names)
    print("\nLikely content XML(s) selected for processing:")
    for n in content_xmls:
        print(f"  - {n}")

    # Exploratory dump of content section XMLs
    dump_raw_xml(hwpx_path, content_xmls)

    # Transform selected XML(s)
    modified: Dict[str, bytes] = {}
    summaries: Dict[str, ReplacementSummary] = {}

    expected_stage_months = {"1": 3, "2": 3, "3": 1}

    with zipfile.ZipFile(hwpx_path, "r") as zf:
        for xp in content_xmls:
            if xp not in zf.namelist():
                continue
            xml_bytes = zf.read(xp)
            new_bytes, summary = transform_section_xml(xml_bytes, values, xp)
            modified[xp] = new_bytes
            summaries[xp] = summary

    build_output_zip(hwpx_path, out_path, modified)

    validation = validate_output(out_path, list(modified.keys()), expected_stage_months)

    print("\n" + "=" * 80)
    print("[SUMMARY] Replacements and edits")
    print("=" * 80)

    for xp, s in summaries.items():
        print(f"\n-- File: {xp} --")

        print("Placeholder replacements:")
        if s.placeholders_replaced:
            for k in sorted(s.placeholders_replaced.keys()):
                print(f"  {k}: {s.placeholders_replaced[k]}")
        else:
            print("  (none)")

        if s.placeholders_missing_keys:
            print("Placeholders with missing JSON keys (left unchanged):")
            for k in sorted(s.placeholders_missing_keys.keys()):
                print(f"  {k}: {s.placeholders_missing_keys[k]}")

        print(f"Budget normalizations (comma removals): {s.budget_normalizations}")

        print("Stage month-span appends:")
        if s.stage_month_appends:
            for stage in sorted(s.stage_month_appends.keys()):
                print(f"  Stage {stage}: {s.stage_month_appends[stage]}")
        else:
            print("  (none)")

        print(f"linesegarray elements removed: {s.linesegarray_removed}")

        print("Modified paragraph ids:")
        if s.modified_paragraph_ids:
            for pid in s.modified_paragraph_ids:
                print(f"  - {pid}")
        else:
            print("  (none)")

    print("\n" + "=" * 80)
    print("[VALIDATION] Output checks")
    print("=" * 80)
    for k, v in validation.items():
        if k == "details":
            continue
        print(f"{k}: {v}")

    if validation.get("details"):
        print("\nDetails:")
        for d in validation["details"]:
            print(f"  - {d}")

    must_be_true = [
        "zip_valid",
        "no_placeholders",
        "stage_month_spans_ok",
        "budget_commas_removed",
        "linesegarray_absent_in_modified_paragraphs",
    ]
    failed = [k for k in must_be_true if not validation.get(k)]
    if failed:
        print("\nERROR: Validation failed:", ", ".join(failed))
        sys.exit(2)

    print("\nOK: Output written and validated.")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""Process an HWPX template with JSON-driven placeholder replacement.

Task requirements implemented:
- Exploratory pass FIRST: ZIP listing + raw XML dump of section file(s)
- Parse XML structurally (no raw XML string replacement)
- Replace all {{...}} placeholders using keys from project_proposal.json
- Normalize budget: remove commas, keep currency symbol (e.g. ₩450,000,000 -> ₩450000000)
- Append computed month spans to 단계1/2/3 schedule lines based on date ranges already present
- Keep Korean labels/static lines unchanged except where placeholders are
- Remove layout-cache elements named linesegarray from every paragraph whose text was modified
- Rebuild output HWPX, preserving all other ZIP entries exactly
- Validate output for placeholders, month spans, budget commas, and linesegarray removal

Output: /root/project_proposal_ready.hwpx

Notes:
- Uses xml.etree.ElementTree (stdlib). lxml is preferred in general, but isn't
  available in this runtime.
"""

from __future__ import annotations

import json
import os
import re
import sys
import zipfile
import xml.etree.ElementTree as ET
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple


DATE_YM_RE = re.compile(r"(\d{4})[.\-/](\d{1,2})(?:[.\-/](\d{1,2}))?")
MONTH_SPAN_RE = re.compile(r"\(\s*(\d+)\s*개월\s*\)")

# Stage markers may appear as "1단계" or "단계1" depending on author.
STAGE_PATTERNS = [
    re.compile(r"\b([1-3])\s*단계\b"),
    re.compile(r"단계\s*([1-3])\b"),
]

# Currency normalization: keep the leading symbol, strip commas from digits.
CURRENCY_RE = re.compile(r"([₩$€¥])\s*([0-9][0-9,]*)")

# Placeholders: allow Korean and other characters; stop at braces.
PLACEHOLDER_RE = re.compile(r"\{\{\s*([^{}]+?)\s*\}\}")


def eprint(*args, **kwargs):
    print(*args, file=sys.stderr, **kwargs)


@dataclass
class ReplacementSummary:
    placeholders_replaced: Dict[str, int] = field(default_factory=dict)
    placeholders_missing_keys: Dict[str, int] = field(default_factory=dict)
    budget_normalizations: int = 0
    stage_month_appends: Dict[str, int] = field(default_factory=dict)  # stage -> count
    linesegarray_removed: int = 0
    modified_paragraph_ids: List[str] = field(default_factory=list)


def find_input_paths() -> Tuple[str, str, str]:
    candidates_hwpx = [
        "/root/project_proposal_template.hwpx",
        os.path.join(os.getcwd(), "project_proposal_template.hwpx"),
    ]
    candidates_json = [
        "/root/project_proposal.json",
        os.path.join(os.getcwd(), "project_proposal.json"),
    ]

    hwpx_path = next((p for p in candidates_hwpx if os.path.exists(p)), None)
    json_path = next((p for p in candidates_json if os.path.exists(p)), None)
    out_path = "/root/project_proposal_ready.hwpx"

    if not hwpx_path:
        raise FileNotFoundError("Template HWPX not found in /root or current directory")
    if not json_path:
        raise FileNotFoundError("JSON data file not found in /root or current directory")

    return hwpx_path, json_path, out_path


def load_json(json_path: str) -> Dict[str, str]:
    with open(json_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    out: Dict[str, str] = {}
    for k, v in data.items():
        if v is None:
            out[k] = ""
        elif isinstance(v, (dict, list)):
            out[k] = json.dumps(v, ensure_ascii=False)
        else:
            out[k] = str(v)
    return out


def list_zip(zip_path: str) -> List[str]:
    with zipfile.ZipFile(zip_path, "r") as zf:
        return zf.namelist()


def choose_content_xmls(zip_names: List[str]) -> List[str]:
    xmls = [n for n in zip_names if n.lower().endswith(".xml")]

    section_like = [
        n
        for n in xmls
        if re.search(r"(^|/)Contents/section\d+\.xml$", n)
        or re.search(r"(^|/)Contents/Section\d+\.xml$", n)
    ]

    if not section_like:
        section_like = [n for n in xmls if "Contents/" in n]

    if not section_like:
        section_like = xmls

    seen = set()
    out = []
    for n in section_like:
        if n not in seen:
            out.append(n)
            seen.add(n)
    return out


def dump_raw_xml(zip_path: str, xml_paths: List[str]) -> Dict[str, bytes]:
    raw: Dict[str, bytes] = {}
    with zipfile.ZipFile(zip_path, "r") as zf:
        for xp in xml_paths:
            try:
                data = zf.read(xp)
            except KeyError:
                continue
            raw[xp] = data

            print("\n" + "=" * 80)
            print(f"[RAW XML DUMP] {xp} ({len(data)} bytes)")
            print("=" * 80)
            print(data.decode("utf-8", errors="replace"))
    return raw


def localname(tag: str) -> str:
    # ElementTree uses {uri}local
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def element_namespace_uri(tag: str) -> Optional[str]:
    if tag.startswith("{"):
        return tag[1:].split("}", 1)[0]
    return None


def build_parent_map(root: ET.Element) -> Dict[ET.Element, ET.Element]:
    parent: Dict[ET.Element, ET.Element] = {}
    for p in root.iter():
        for c in list(p):
            parent[c] = p
    return parent


def iter_text_elements(root: ET.Element):
    for el in root.iter():
        if localname(el.tag) == "t":
            yield el


def iter_paragraph_elements(root: ET.Element):
    for el in root.iter():
        if localname(el.tag) == "p":
            yield el


def paragraph_text(par: ET.Element) -> str:
    parts: List[str] = []
    for t in par.iter():
        if localname(t.tag) == "t" and t.text is not None:
            parts.append(t.text)
    return "".join(parts)


def find_stage_number(text: str) -> Optional[str]:
    for pat in STAGE_PATTERNS:
        m = pat.search(text)
        if m:
            return m.group(1)
    return None


def extract_year_months(text: str) -> List[Tuple[int, int]]:
    out: List[Tuple[int, int]] = []
    for y, m, _d in DATE_YM_RE.findall(text):
        try:
            yy = int(y)
            mm = int(m)
        except ValueError:
            continue
        if 1 <= mm <= 12:
            out.append((yy, mm))
    return out


def compute_month_span_inclusive(start_ym: Tuple[int, int], end_ym: Tuple[int, int]) -> int:
    sy, sm = start_ym
    ey, em = end_ym
    months = (ey - sy) * 12 + (em - sm) + 1
    if months < 1:
        return 1
    return months


def append_stage_month_span(text: str) -> Tuple[str, Optional[int], Optional[str]]:
    stage = find_stage_number(text)
    if stage is None:
        return text, None, None

    if MONTH_SPAN_RE.search(text):
        return text, None, stage

    yms = extract_year_months(text)
    if not yms:
        return text, None, stage

    if len(yms) >= 2:
        start_ym, end_ym = yms[0], yms[1]
    else:
        start_ym = end_ym = yms[0]

    months = compute_month_span_inclusive(start_ym, end_ym)

    spacer = "" if text.endswith(" ") else " "
    return text + f"{spacer}({months}개월)", months, stage


def normalize_budget_in_text(text: str) -> Tuple[str, int]:
    count = 0

    def repl(m: re.Match) -> str:
        nonlocal count
        sym = m.group(1)
        digits = m.group(2)
        if "," in digits:
            count += 1
            digits = digits.replace(",", "")
        return f"{sym}{digits}"

    return CURRENCY_RE.sub(repl, text), count


def replace_placeholders_in_text(text: str, values: Dict[str, str], summary: ReplacementSummary) -> str:
    def repl(m: re.Match) -> str:
        key = m.group(1).strip()
        if key in values:
            summary.placeholders_replaced[key] = summary.placeholders_replaced.get(key, 0) + 1
            return values[key]
        summary.placeholders_missing_keys[key] = summary.placeholders_missing_keys.get(key, 0) + 1
        return m.group(0)

    return PLACEHOLDER_RE.sub(repl, text)


def find_ancestor_paragraph(node: ET.Element, parent_map: Dict[ET.Element, ET.Element]) -> Optional[ET.Element]:
    cur = node
    while cur in parent_map:
        cur = parent_map[cur]
        if localname(cur.tag) == "p":
            return cur
    return None


def remove_linesegarray_from_paragraph(par: ET.Element, parent_map: Dict[ET.Element, ET.Element], summary: ReplacementSummary):
    # Find all descendant linesegarray elements and remove from their immediate parent.
    to_remove: List[ET.Element] = []
    for el in par.iter():
        if localname(el.tag) == "linesegarray":
            to_remove.append(el)

    for el in to_remove:
        parent = parent_map.get(el)
        if parent is None:
            continue
        parent.remove(el)
        summary.linesegarray_removed += 1


def transform_section_xml(xml_bytes: bytes, values: Dict[str, str], label: str) -> Tuple[bytes, ReplacementSummary]:
    root = ET.fromstring(xml_bytes)

    print("\n" + "-" * 80)
    print(f"[INSPECT] {label}")
    print(f"Root tag: {root.tag}")
    ns_uri = element_namespace_uri(root.tag)
    if ns_uri:
        print(f"Root namespace URI: {ns_uri}")
    else:
        print("Root namespace URI: (none)")

    parent_map = build_parent_map(root)
    summary = ReplacementSummary()

    modified_paragraphs: List[ET.Element] = []
    modified_set = set()

    # Pass 1: per-<t> edits (preserve runs)
    for t in iter_text_elements(root):
        if t.text is None:
            continue

        original = t.text
        new = original

        if "{{" in new and "}}" in new:
            new = replace_placeholders_in_text(new, values, summary)

        new, bcount = normalize_budget_in_text(new)
        summary.budget_normalizations += bcount

        appended, _months, stage = append_stage_month_span(new)
        if appended != new:
            new = appended
            if stage is not None:
                summary.stage_month_appends[stage] = summary.stage_month_appends.get(stage, 0) + 1

        if new != original:
            t.text = new
            par = find_ancestor_paragraph(t, parent_map)
            if par is not None and id(par) not in modified_set:
                modified_set.add(id(par))
                modified_paragraphs.append(par)

    # Pass 2: paragraph-level fix-up (handles placeholders split across multiple <t> nodes)
    for par in iter_paragraph_elements(root):
        combined = paragraph_text(par)
        if "{{" not in combined and "단계" not in combined and not CURRENCY_RE.search(combined):
            continue

        new_combined = combined

        if "{{" in new_combined and "}}" in new_combined:
            new_combined = replace_placeholders_in_text(new_combined, values, summary)

        new_combined, bcount = normalize_budget_in_text(new_combined)
        summary.budget_normalizations += bcount

        appended, _months, stage = append_stage_month_span(new_combined)
        if appended != new_combined:
            new_combined = appended
            if stage is not None:
                summary.stage_month_appends[stage] = summary.stage_month_appends.get(stage, 0) + 1

        if new_combined == combined:
            continue

        t_nodes = [n for n in par.iter() if localname(n.tag) == "t"]
        if not t_nodes:
            continue

        old_lens = [len(n.text or "") for n in t_nodes]
        remaining = new_combined
        for i, node in enumerate(t_nodes):
            if i == len(t_nodes) - 1:
                chunk = remaining
            else:
                take = old_lens[i]
                chunk = remaining[:take]
            node.text = chunk
            remaining = remaining[len(chunk):]

        if id(par) not in modified_set:
            modified_set.add(id(par))
            modified_paragraphs.append(par)

    # Remove layout-cache elements for any paragraph we modified
    for par in modified_paragraphs:
        remove_linesegarray_from_paragraph(par, parent_map, summary)
        pid = par.get("id")
        if pid is None:
            # fallback identifier
            pid = f"(no-id)@{label}#{len(summary.modified_paragraph_ids)}"
        summary.modified_paragraph_ids.append(pid)

    out_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    return out_bytes, summary


def clone_zipinfo(info: zipfile.ZipInfo) -> zipfile.ZipInfo:
    zi = zipfile.ZipInfo(filename=info.filename, date_time=info.date_time)
    zi.compress_type = info.compress_type
    zi.comment = info.comment
    zi.extra = info.extra
    zi.create_system = info.create_system
    zi.create_version = info.create_version
    zi.extract_version = info.extract_version
    zi.flag_bits = info.flag_bits
    zi.internal_attr = info.internal_attr
    zi.external_attr = info.external_attr
    return zi


def build_output_zip(template_path: str, out_path: str, modified_xml: Dict[str, bytes]):
    with zipfile.ZipFile(template_path, "r") as zin:
        with zipfile.ZipFile(out_path, "w") as zout:
            for info in zin.infolist():
                data = zin.read(info.filename)
                if info.filename in modified_xml:
                    data = modified_xml[info.filename]
                zout.writestr(clone_zipinfo(info), data)


def validate_output(out_path: str, modified_xml_paths: List[str], expected_stage_months: Dict[str, Optional[int]]):
    results = {
        "zip_valid": False,
        "no_placeholders": True,
        "stage_month_spans_ok": True,
        "budget_commas_removed": True,
        "korean_stage_labels_present": True,
        "linesegarray_absent_in_modified_paragraphs": True,
        "details": [],
    }

    with zipfile.ZipFile(out_path, "r") as zf:
        bad = zf.testzip()
        results["zip_valid"] = (bad is None)
        if bad is not None:
            results["details"].append(f"Zip testzip failed at: {bad}")

        for xp in modified_xml_paths:
            xml_bytes = zf.read(xp)
            xml_text = xml_bytes.decode("utf-8", errors="replace")

            if "{{" in xml_text or "}}" in xml_text:
                results["no_placeholders"] = False
                results["details"].append(f"Placeholders still present in {xp}")

            if re.search(r"[₩$€¥]\s*\d{1,3}(,\d{3})+", xml_text):
                results["budget_commas_removed"] = False
                results["details"].append(f"Found currency amount with commas in {xp}")

            root = ET.fromstring(xml_bytes)

            stage_found = {"1": False, "2": False, "3": False}
            stage_ok = {"1": True, "2": True, "3": True}

            for par in iter_paragraph_elements(root):
                txt = paragraph_text(par)
                stage = find_stage_number(txt)
                if stage is None or stage not in stage_found:
                    continue

                stage_found[stage] = True

                mm = MONTH_SPAN_RE.search(txt)
                if not mm:
                    stage_ok[stage] = False
                    results["details"].append(f"Missing month span on stage{stage} line in {xp}: {txt}")
                    continue

                actual = int(mm.group(1))
                yms = extract_year_months(txt)
                if yms:
                    if len(yms) >= 2:
                        computed = compute_month_span_inclusive(yms[0], yms[1])
                    else:
                        computed = 1
                    if computed != actual:
                        stage_ok[stage] = False
                        results["details"].append(
                            f"Stage{stage} month span mismatch in {xp}: computed {computed}, found {actual}"
                        )

                exp = expected_stage_months.get(stage)
                if exp is not None and exp != actual:
                    # Not fatal by itself (task requires compute-from-dates), but record.
                    results["details"].append(
                        f"Stage{stage} months differ from expected ({exp}) in {xp}: found {actual}"
                    )

            if not all(stage_found.values()):
                results["korean_stage_labels_present"] = False
                results["details"].append(f"Not all stage lines found in {xp}: {stage_found}")

            if not all(stage_ok.values()):
                results["stage_month_spans_ok"] = False

            # Ensure no linesegarray exists inside paragraphs that look modified.
            for par in iter_paragraph_elements(root):
                txt = paragraph_text(par)
                if not txt:
                    continue
                modified_like = (
                    bool(PLACEHOLDER_RE.search(txt))
                    or ("개월" in txt and find_stage_number(txt) is not None)
                    or bool(CURRENCY_RE.search(txt))
                )
                if not modified_like:
                    continue

                has_linesegarray = any(localname(el.tag) == "linesegarray" for el in par.iter())
                if has_linesegarray:
                    results["linesegarray_absent_in_modified_paragraphs"] = False
                    results["details"].append(f"Found linesegarray inside modified-like paragraph in {xp}: {txt}")
                    break

    return results


def main():
    hwpx_path, json_path, out_path = find_input_paths()

    print(f"Template HWPX: {hwpx_path}")
    print(f"JSON data:     {json_path}")
    print(f"Output HWPX:   {out_path}")

    values = load_json(json_path)

    print("\n" + "=" * 80)
    print("[EXPLORATION] ZIP listing")
    print("=" * 80)
    zip_names = list_zip(hwpx_path)
    for n in zip_names:
        print(n)

    xml_paths = [n for n in zip_names if n.lower().endswith(".xml")]
    print("\nXML files found:")
    for n in xml_paths:
        print(f"  - {n}")

    content_xmls = choose_content_xmls(zip_names)
    print("\nLikely content XML(s) selected for processing:")
    for n in content_xmls:
        print(f"  - {n}")

    # Exploratory dump of content section XMLs
    dump_raw_xml(hwpx_path, content_xmls)

    # Transform selected XML(s)
    modified: Dict[str, bytes] = {}
    summaries: Dict[str, ReplacementSummary] = {}

    expected_stage_months = {"1": 3, "2": 3, "3": 1}

    with zipfile.ZipFile(hwpx_path, "r") as zf:
        for xp in content_xmls:
            if xp not in zf.namelist():
                continue
            xml_bytes = zf.read(xp)
            new_bytes, summary = transform_section_xml(xml_bytes, values, xp)
            modified[xp] = new_bytes
            summaries[xp] = summary

    build_output_zip(hwpx_path, out_path, modified)

    validation = validate_output(out_path, list(modified.keys()), expected_stage_months)

    print("\n" + "=" * 80)
    print("[SUMMARY] Replacements and edits")
    print("=" * 80)

    for xp, s in summaries.items():
        print(f"\n-- File: {xp} --")

        print("Placeholder replacements:")
        if s.placeholders_replaced:
            for k in sorted(s.placeholders_replaced.keys()):
                print(f"  {k}: {s.placeholders_replaced[k]}")
        else:
            print("  (none)")

        if s.placeholders_missing_keys:
            print("Placeholders with missing JSON keys (left unchanged):")
            for k in sorted(s.placeholders_missing_keys.keys()):
                print(f"  {k}: {s.placeholders_missing_keys[k]}")

        print(f"Budget normalizations (comma removals): {s.budget_normalizations}")

        print("Stage month-span appends:")
        if s.stage_month_appends:
            for stage in sorted(s.stage_month_appends.keys()):
                print(f"  Stage {stage}: {s.stage_month_appends[stage]}")
        else:
            print("  (none)")

        print(f"linesegarray elements removed: {s.linesegarray_removed}")

        print("Modified paragraph ids:")
        if s.modified_paragraph_ids:
            for pid in s.modified_paragraph_ids:
                print(f"  - {pid}")
        else:
            print("  (none)")

    print("\n" + "=" * 80)
    print("[VALIDATION] Output checks")
    print("=" * 80)
    for k, v in validation.items():
        if k == "details":
            continue
        print(f"{k}: {v}")

    if validation.get("details"):
        print("\nDetails:")
        for d in validation["details"]:
            print(f"  - {d}")

    must_be_true = [
        "zip_valid",
        "no_placeholders",
        "stage_month_spans_ok",
        "budget_commas_removed",
        "linesegarray_absent_in_modified_paragraphs",
    ]
    failed = [k for k in must_be_true if not validation.get(k)]
    if failed:
        print("\nERROR: Validation failed:", ", ".join(failed))
        sys.exit(2)

    print("\nOK: Output written and validated.")


if __name__ == "__main__":
    main()

